def count_attacked_squares(knights, board_size):
    attacked = set()
    for (x, y) in knights:
        for dx, dy in [(1, 2), (1, -2), (-1, 2), (-1, -2), (2, 1), (2, -1), (-2, 1), (-2, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < board_size[0] and 0 <= ny < board_size[1]:
                attacked.add((nx, ny))
    return len(attacked)

